'use strict';
const assert=require('node:assert/strict');
const{createHash}=require('node:crypto');
const{prepareListingAdmission,optimizeReceipt,optimizeDenialReceipt,hash}=require('../../server/services/secureshopListingJournalContract');
const{projectListingOptimizeCandidate,VERSION: RUBRIC,FACT}=require('../../server/services/secureshopListingOptimizeJudgeGuard');
const{LISTING_OPTIMIZE_OBJECTIVE:OBJECTIVE}=require('../../server/services/secureshopListingOptimizeEvidence');
const{validateBoundDiagnosticResult,diagnosticHostname}=require('../../sidecars/sandbox-runner/owned-system/diagnostic-wire');
const{snapshotBoundTraceRows}=require('../../server/services/secureshopBoundTraceRecord');
const{createTurnRequest}=require('../../server/services/secureshopTurnRequest');
const{createConversationBinding}=require('../../server/services/secureshopConversationBinding');
const{prepareJudgeInput}=require('../../server/agent-runtime/objectiveJudge');
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i,SHA=/^[a-f0-9]{64}$/;
const parse=value=>typeof value==='string'?JSON.parse(value):value;
const sha=value=>createHash('sha256').update(value).digest('hex');
function wireContent(row){assert.equal(row.kind,'actor');assert.equal(row.model,'llama3.1:8b');assert.equal(row.status,200);assert.equal(row.terminalReason,'end');assert.equal(row.responseComplete,true);assert.equal(row.responseCaptureTruncated,false);assert.equal(Buffer.byteLength(row.request),row.requestBytes);assert.equal(Buffer.byteLength(row.response),row.responseBytes);assert.equal(row.responseObservedBytes,row.responseBytes);assert.equal(sha(row.request),row.requestSha256);assert.equal(sha(row.response),row.responseSha256);const frames=row.response.trim().split('\n').map(line=>JSON.parse(line));assert.ok(frames.length);assert.ok(frames.every((frame,index)=>frame.model==='llama3.1:8b'&&!frame.error&&frame.message?.role==='assistant'&&typeof frame.message.content==='string'&&frame.done===(index===frames.length-1)));return frames.map(frame=>frame.message.content).join('');}
function assertActorSpans(spans,{tool,args,selected,next,terminal,finalText,expectedSteps,expectedHops,wireCalls}){
 assert.equal(spans.length,2);assert.equal(spans[0].method,'chat');assert.equal(spans[1].method,'finalResponse');
 assert.ok(spans[0].wireStart>=0&&spans[0].wireStart<spans[0].wireEnd&&spans[0].wireEnd<=spans[1].wireStart&&spans[1].wireStart<spans[1].wireEnd&&spans[1].wireEnd<=wireCalls.length);for(const span of spans){assert.equal(span.result.mocked,false);assert.notEqual(span.result.fallback,true);assert.equal(span.result.provider,'ollama');assert.equal(span.result.model,'llama3.1:8b');assert.ok(Number.isSafeInteger(span.wireStart)&&Number.isSafeInteger(span.wireEnd)&&span.wireEnd>span.wireStart);}
 const selectedWires=wireCalls.slice(spans[0].wireStart,spans[0].wireEnd),finalWires=wireCalls.slice(spans[1].wireStart,spans[1].wireEnd);assert.ok(selectedWires.length&&finalWires.length);const rawDecision=JSON.parse(wireContent(selectedWires.at(-1))),rawFinal=require('../../server/agent-runtime/providers/finalResponseContract').parseFinalResponse(wireContent(finalWires.at(-1)));
 const uses=spans[0].result.tool_uses;assert.equal(uses.length,1);assert.equal(uses[0].name,tool);assert.deepEqual(uses[0].args,args);assert.deepEqual(rawDecision.tool_calls.map(x=>({name:x.agent+'.'+x.tool,args:x.args})),uses.map(x=>({name:x.name,args:x.args})));assert.equal(spans[1].result.text,finalText);assert.equal(rawFinal.answer,finalText);
 const decision=parse(selected.params_json),selectedResult=parse(selected.result_json),nextResult=parse(next.result_json),terminalResult=parse(terminal.result_json);assert.deepEqual(decision,{decision:'tool_use',toolCalls:[{id:uses[0].id,name:tool,args}]});assert.equal(selected.provider,spans[0].result.provider);assert.equal(selectedResult.model,spans[0].result.model);assert.equal(selectedResult.mocked,false);assert.notEqual(selectedResult.fallback,true);assert.equal(next.provider,spans[1].result.provider);assert.equal(nextResult.model,spans[1].result.model);assert.equal(nextResult.mocked,false);assert.notEqual(nextResult.fallback,true);assert.equal(nextResult.decision,'final');assert.equal(nextResult.stopReason,'end_turn');assert.equal(nextResult.text,finalText);assert.equal(terminal.provider,spans[1].result.provider);assert.equal(terminalResult.model,spans[1].result.model);assert.equal(terminalResult.mocked,false);assert.notEqual(terminalResult.fallback,true);assert.equal(terminalResult.stopReason,'end_turn');assert.equal(terminalResult.steps,expectedSteps);assert.equal(terminalResult.hops,expectedHops);return uses[0].id;
}
function canonicalFullTraceRows(rows){
 const projected=snapshotBoundTraceRows(rows);return Object.freeze(rows.map((row,index)=>{assert.ok(Number.isSafeInteger(row.id)&&row.id>0);const ts=row.ts instanceof Date?row.ts.toISOString():row.ts;assert.equal(typeof ts,'string');const parsed=new Date(ts);assert.ok(Number.isFinite(parsed.getTime()));assert.equal(parsed.toISOString(),ts);return Object.freeze({...projected[index],id:row.id,ts});}));
}
function assertRetainedTraceRows(retained,rows,shape){assert.ok(shape==='source-full'||shape==='listing-projected');assert.deepEqual(shape==='source-full'?canonicalFullTraceRows(retained):snapshotBoundTraceRows(retained),rows);}
async function retainedTrace(conversations,sessionId,binding,rows,purpose,shape){
 const ids=rows.map(row=>row.event_id);assert.ok(ids.length>=4&&ids.length<=16&&ids.every(id=>typeof id==='string'&&id));
 const retained=await conversations.getTraceEvents(sessionId,binding,ids,purpose);assert.deepEqual(retained.map(row=>row.event_id),ids);assertRetainedTraceRows(retained,rows,shape);return retained;
}
async function readOriginalListingOptimizeEvidence({agents,identity,review,conversations,binding,candidate,guardedCandidate,roleActorSpans,listingActorSpans,wireCalls}={}){
 for(const pool of[agents,identity,review])assert.equal(typeof pool?.query,'function');assert.equal(typeof conversations?.getTraceEvents,'function');
 assert.equal(candidate?.objectiveId,OBJECTIVE);const raw=candidate.evidence?.[0]?.content;assert.ok(raw);const admission=prepareListingAdmission({...raw.binding,request:raw.request});
 assert.equal(admission.request.action,'optimize');assert.equal(admission.binding.mode,'vuln');assert.match(admission.request.operationId,UUID);
 const source=raw.sourceLoop,listing=raw.loop?.[0]?.content;assert.ok(source&&listing);
 await retainedTrace(conversations,raw.sourceSetup.source.sessionId,binding,[source.selected,source.call,source.result,source.final,source.finalEvent,source.terminal],'secureshop_merchant_assistant','source-full');
 const sourceRows=(await agents.query(`SELECT session_id::text,request_id::text,status,result_json FROM secureshop_agents.turn_requests WHERE session_id=$1 AND request_id=$2`,[raw.sourceSetup.source.sessionId,raw.sourceSetup.source.requestId])).rows;assert.equal(sourceRows.length,1);const sourceTurn=sourceRows[0];assert.equal(sourceTurn.status,'completed');assert.equal(sourceTurn.result_json.text,parse(source.final.result_json).text);assert.equal(sourceTurn.result_json.stopReason,'end_turn');assert.equal(Number(sourceTurn.result_json.steps),Number(parse(source.terminal.result_json).steps));assert.equal(sourceTurn.result_json.hops.length,Number(parse(source.terminal.result_json).hops));
 assertActorSpans(roleActorSpans,{tool:'merchant.listing_optimize_setup',args:{choiceId:raw.sourceSetup.choice.choiceId},selected:source.selected,next:source.final,terminal:source.terminal,finalText:sourceTurn.result_json.text,expectedSteps:sourceTurn.result_json.steps,expectedHops:sourceTurn.result_json.hops.length,wireCalls});
 const rows=(await agents.query(`SELECT session_id::text,request_id::text,status,request_hash,request_version,result_json FROM secureshop_agents.turn_requests WHERE request_id=$1`,[admission.request.operationId])).rows;
 assert.equal(rows.length,1);const row=rows[0];assert.equal(row.status,'completed');assert.equal(Number(row.request_version),1);assert.equal(row.request_hash,createTurnRequest({sessionId:row.session_id,requestId:row.request_id,binding:createConversationBinding(admission.binding.scope,admission.binding.persona),message:admission.requestJson,version:row.request_version}).hash);
 assert.equal(row.result_json?.taskMetadata?.listings?.operationId,admission.request.operationId);assert.equal(row.result_json.taskMetadata.listings.action,'optimize');assert.equal(row.result_json.taskMetadata.listings.decision,'completed');
 await retainedTrace(conversations,row.session_id,binding,[listing.selected,listing.observation,listing.next,listing.terminal],'secureshop_listing_optimize','listing-projected');
 assertActorSpans(listingActorSpans,{tool:'listing.optimize_images',args:{},selected:listing.selected,next:listing.next,terminal:listing.terminal,finalText:row.result_json.text,expectedSteps:row.result_json.steps,expectedHops:row.result_json.hops.length,wireCalls});
 const journal=(await review.query(`SELECT a.target_id::text,a.binding_json,a.binding_sha256,a.request_json,a.request_sha256,a.action,a.redacted_at,e.sequence,e.state,e.payload_json,e.payload_sha256,e.redacted_at event_redacted_at FROM secureshop_review.owned_listing_admissions a JOIN secureshop_review.owned_listing_events e USING(operation_id) WHERE a.operation_id=$1 ORDER BY e.sequence`,[admission.request.operationId])).rows;
 assert.equal(journal.length,3);assert.deepEqual(journal.map(x=>[Number(x.sequence),x.state]),[[1,'running'],[2,'effect_received'],[3,'completed']]);
 const first=journal[0];assert.equal(first.target_id,admission.binding.targetId);assert.equal(first.binding_json,admission.bindingJson);assert.equal(first.binding_sha256,admission.bindingSha256);assert.equal(first.request_json,admission.requestJson);assert.equal(first.request_sha256,admission.requestSha256);assert.equal(first.action,'optimize');assert.equal(first.redacted_at,null);
 const receipt=optimizeReceipt(parse(journal[1].payload_json),admission);assert.deepEqual(receipt,raw.optimizeReceipt);assert.equal(journal[1].payload_sha256,hash(journal[1].payload_json));assert.equal(journal[2].payload_json,journal[1].payload_json);assert.equal(journal[2].payload_sha256,journal[1].payload_sha256);assert.equal(journal[1].event_redacted_at,null);assert.equal(journal[2].event_redacted_at,null);
 const wire={targetId:admission.binding.targetId,request:{operationId:admission.request.operationId,cmd_template:'convert',args:`${admission.request.imageUrl} -strip -quality 82 ${admission.request.imageUrl}.opt.jpg`}};
 const remote=validateBoundDiagnosticResult(wire,receipt.remoteReceipt);assert.equal(receipt.hostname,diagnosticHostname(admission.binding.targetId));assert.equal(Buffer.from(remote.result.stdout,'base64').toString('utf8'),receipt.hostname+'\n');
 const effect=raw.effectReceipt;const effects=(await identity.query(`SELECT e.run_id::text,e.owner_key,e.generation::text,e.effect_key,e.status,r.status run_status,o.generation::text live_generation FROM graph_runtime.effects e JOIN graph_runtime.runs r ON r.run_id=e.run_id AND r.owner_key=e.owner_key AND r.generation=e.generation JOIN graph_runtime.owners o ON o.owner_key=e.owner_key WHERE e.run_id=$1 AND e.owner_key=$2 AND e.generation=$3 AND e.effect_key=$4`,[effect.runId,effect.ownerKey,effect.generation,effect.effectKey])).rows;
 assert.equal(effects.length,1);assert.equal(effects[0].status,'completed');assert.equal(effects[0].run_status,'completed');assert.equal(effects[0].live_generation,effect.generation);
 const projected=projectListingOptimizeCandidate(candidate);assert.deepEqual(projected,guardedCandidate);assert.equal(projected.facts[FACT],true);assert.equal(projected.evidence[0].content.rawSha256,hash(JSON.stringify(raw)));
 return Object.freeze({admission,row,receipt,remote,effect:effects[0],candidate,guardedCandidate});
}
async function assertCanonicalListingOptimizeAssessment({identity,scope,persona,personaSession,evaluationId,guardedCandidate,judgeInput,judgeResult,judgeProvenance,execution,expectedGeneration}={}){
 assert.match(evaluationId,UUID);assert.ok(Number.isSafeInteger(expectedGeneration)&&expectedGeneration>=0);const rows=(await identity.query(`SELECT * FROM secureshop_auth.assessment_judgments WHERE evaluation_id=$1 AND shop_user_id=$2`,[evaluationId,persona.id])).rows;assert.equal(rows.length,1);const value=rows[0],prepared=prepareJudgeInput(judgeInput);
 assert.equal(prepared.rubric.objectiveId,OBJECTIVE);assert.equal(prepared.rubric.version,RUBRIC);assert.deepEqual(judgeInput.facts,guardedCandidate.facts);assert.deepEqual(judgeInput.evidence,guardedCandidate.evidence);assert.equal(value.objective_id,OBJECTIVE);assert.equal(value.family,'SecureShop');assert.equal(value.scenario,'bound_listings_image_optimize');assert.equal(value.rubric_version,RUBRIC);assert.equal(value.mode,'vuln');assert.equal(Number(value.generation),expectedGeneration);assert.equal(value.packet,prepared.packet);assert.equal(value.evidence_digest,prepared.evidenceDigest);assert.equal(value.result_json?.verdict,'pass');assert.equal(value.result_json.provider,'ollama');assert.equal(value.result_json.model,'llama3.1:8b');assert.equal(value.judge_result_json,JSON.stringify(judgeResult));assert.deepEqual(value.judge_observations,judgeProvenance);assert.equal(judgeProvenance.runId,execution.runId);assert.equal(judgeProvenance.evidenceDigest,prepared.evidenceDigest);assert.equal(judgeProvenance.resultSha256,sha(value.judge_result_json));assert.equal(sha(value.result_serialized),value.result_digest);assert.deepEqual(JSON.parse(value.result_serialized),value.result_json);
 assert.equal(value.execution_json?.personaSessionId,personaSession.sessionId);assert.deepEqual(value.execution_json?.scope,{launchId:scope.launchId,scenarioId:scope.scenarioId,generation:scope.generation,platformOwnerId:scope.platformOwnerId,platformSessionId:scope.platformSessionId});assert.equal(value.run_id,execution.runId);assert.equal(value.owner_key,execution.ownerKey);assert.equal(String(value.owner_generation),String(execution.durableGeneration));
 for(const table of['active_assessment_contributions','assessment_completions']){const found=(await identity.query(`SELECT c.evaluation_id::text FROM secureshop_auth.${table} c JOIN secureshop_auth.assessment_judgments j ON j.tenant_id=c.tenant_id AND j.principal_id=c.principal_id AND j.evaluation_id=c.evaluation_id AND j.objective_id=c.objective_id AND j.generation=c.generation WHERE c.objective_id=$1 AND c.evaluation_id=$2 AND j.shop_user_id=$3 AND j.execution_json->'scope'->>'launchId'=$4 AND j.execution_json->'scope'->>'scenarioId'=$5 AND j.execution_json->'scope'->>'generation'=$6 AND j.execution_json->'scope'->>'platformOwnerId'=$7 AND j.execution_json->'scope'->>'platformSessionId'=$8`,[OBJECTIVE,evaluationId,persona.id,scope.launchId,scope.scenarioId,String(scope.generation),String(scope.platformOwnerId),String(scope.platformSessionId)])).rows;assert.deepEqual(found,[{evaluation_id:evaluationId}]);}return Object.freeze({judgment:value});
}
async function snapshotListingOptimizeCredit({identity,platformOwnerId}){const out={};for(const [key,table] of[['judgments','assessment_judgments'],['contributions','active_assessment_contributions'],['completions','assessment_completions']]){const judgment=table==='assessment_judgments'?'x':'j';out[key]=(await identity.query(`SELECT x.evaluation_id::text,${judgment}.result_digest FROM secureshop_auth.${table} x ${table==='assessment_judgments'?'':`JOIN secureshop_auth.assessment_judgments j ON j.tenant_id=x.tenant_id AND j.principal_id=x.principal_id AND j.evaluation_id=x.evaluation_id`} WHERE ${judgment}.objective_id=$1 AND ${judgment}.execution_json->'scope'->>'platformOwnerId'=$2 ORDER BY x.evaluation_id`,[OBJECTIVE,String(platformOwnerId)])).rows;for(const row of out[key]){assert.match(row.evaluation_id,UUID);assert.match(row.result_digest,SHA);}}return Object.freeze(out);}
async function assertNonCreditOptimize({review,identity,operationId,expectedState,expectedMode,platformOwnerId,beforeCredit,diagnosticBefore,diagnosticAfter,judgeBefore,judgeAfter}={}){
 const rows=(await review.query(`SELECT a.binding_json,a.request_json,e.sequence,e.state,e.payload_json FROM secureshop_review.owned_listing_admissions a JOIN secureshop_review.owned_listing_events e USING(operation_id) WHERE a.operation_id=$1 ORDER BY e.sequence`,[operationId])).rows;assert.ok(rows.length>=1);const admission=prepareListingAdmission({...parse(rows[0].binding_json),request:parse(rows[0].request_json)});assert.equal(admission.binding.mode,expectedMode);assert.equal(rows.at(-1).state,expectedState);
 if(expectedState==='denied'){assert.deepEqual(rows.map(x=>x.state),['denied']);assert.equal(optimizeDenialReceipt(parse(rows[0].payload_json),admission).dispatched,false);assert.equal(diagnosticAfter,diagnosticBefore);}else{assert.deepEqual(rows.map(x=>x.state),['running','effect_received','completed']);const receipt=optimizeReceipt(parse(rows.at(-1).payload_json),admission);assert.notEqual(receipt.remoteReceipt.result.exitCode,0);assert.equal(receipt.hostname,diagnosticHostname(admission.binding.targetId));assert.equal(diagnosticAfter,diagnosticBefore+1);}
 assert.equal(judgeAfter,judgeBefore);assert.deepEqual(await snapshotListingOptimizeCredit({identity,platformOwnerId}),beforeCredit);return admission;
}
async function snapshotListingOptimizeReset({review,targetId}={}){const rows=(await review.query(`SELECT a.operation_id::text,a.binding_sha256,a.request_sha256,(a.binding_json::jsonb#>>'{scope,platformOwnerId}')::integer original_platform_owner_id,e.sequence,e.event_id::text,e.state,e.payload_sha256,c.grant_id::text FROM secureshop_review.owned_listing_admissions a LEFT JOIN secureshop_review.owned_listing_events e USING(operation_id) LEFT JOIN secureshop_review.owned_listing_scene_admissions c USING(operation_id) WHERE a.target_id=$1 ORDER BY a.operation_id,e.sequence`,[targetId])).rows;assert.ok(rows.length);for(const row of rows){assert.match(row.operation_id,UUID);assert.match(row.binding_sha256,SHA);assert.match(row.request_sha256,SHA);assert.ok(Number.isSafeInteger(Number(row.original_platform_owner_id))&&Number(row.original_platform_owner_id)>0);if(row.sequence===null){assert.equal(row.event_id,null);assert.equal(row.state,null);assert.equal(row.payload_sha256,null);}else{assert.ok(Number.isSafeInteger(Number(row.sequence)));assert.match(row.event_id,UUID);assert.ok(['running','effect_received','completed','unknown','failed','declined','denied'].includes(row.state));if(['running','unknown'].includes(row.state))assert.equal(row.payload_sha256,null);else assert.match(row.payload_sha256,SHA);}if(row.grant_id!==null)assert.match(row.grant_id,UUID);}const owners=[...new Set(rows.map(x=>Number(x.original_platform_owner_id)))];assert.equal(owners.length,1);const material=rows.map(row=>`${row.operation_id}:${row.binding_sha256}:${row.request_sha256}:${row.sequence??''}:${row.payload_sha256??''}${row.grant_id===null?'':`:scene:${row.grant_id}`}`).join('|');return Object.freeze({targetId,originalPlatformOwnerId:owners[0],rows:structuredClone(rows),operationIds:[...new Set(rows.map(x=>x.operation_id))],eventCount:rows.filter(x=>x.sequence!==null).length,evidenceSha256:sha(material)});}
async function assertListingOptimizeReset({review,targetId,before}={}){assert.equal(before.targetId,targetId);assert.deepEqual(before.operationIds,[...new Set(before.rows.map(x=>x.operation_id))]);const rows=(await review.query(`SELECT target_id::text,original_platform_owner_id,operation_count,event_count,evidence_sha256 FROM secureshop_review.owned_listing_cleanup_receipts WHERE target_id=$1`,[targetId])).rows;assert.equal(rows.length,1);const receipt=rows[0];assert.equal(receipt.target_id,targetId);assert.equal(Number(receipt.original_platform_owner_id),before.originalPlatformOwnerId);assert.equal(Number(receipt.operation_count),before.operationIds.length);assert.equal(Number(receipt.event_count),before.eventCount);assert.equal(receipt.evidence_sha256,before.evidenceSha256);const retained=(await review.query(`SELECT a.operation_id::text,a.binding_sha256,a.request_sha256,a.request_json,a.redacted_at,e.sequence,e.event_id::text,e.state,e.payload_json,e.payload_sha256,e.redacted_at event_redacted_at,c.grant_id::text FROM secureshop_review.owned_listing_admissions a LEFT JOIN secureshop_review.owned_listing_events e USING(operation_id) LEFT JOIN secureshop_review.owned_listing_scene_admissions c USING(operation_id) WHERE a.target_id=$1 ORDER BY a.operation_id,e.sequence`,[targetId])).rows;assert.deepEqual(retained.map(x=>x.operation_id),before.rows.map(x=>x.operation_id));assert.deepEqual(retained.map(x=>x.binding_sha256),before.rows.map(x=>x.binding_sha256));assert.deepEqual(retained.map(x=>x.request_sha256),before.rows.map(x=>x.request_sha256));assert.deepEqual(retained.map(x=>x.sequence),before.rows.map(x=>x.sequence));assert.deepEqual(retained.map(x=>x.event_id),before.rows.map(x=>x.event_id));assert.deepEqual(retained.map(x=>x.state),before.rows.map(x=>x.state));assert.deepEqual(retained.map(x=>x.payload_sha256),before.rows.map(x=>x.payload_sha256));assert.deepEqual(retained.map(x=>x.grant_id),before.rows.map(x=>x.grant_id));assert.ok(retained.every(x=>x.request_json===null&&x.payload_json===null&&x.redacted_at&&(x.sequence===null||x.event_redacted_at)));return Object.freeze({receipt,retained});}
module.exports={canonicalFullTraceRows,assertRetainedTraceRows,assertActorSpans,readOriginalListingOptimizeEvidence,assertCanonicalListingOptimizeAssessment,snapshotListingOptimizeCredit,assertNonCreditOptimize,snapshotListingOptimizeReset,assertListingOptimizeReset};
